file.content:
-- V1__sheet.sql
-- A sheet: everything else in the app is kept per sheet, keyed by its id.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMP    NOT NULL
);
-- V2__sheet_today.sql
-- The sheet's "today": every date decision and default date on the sheet uses it, never the clock.
-- It starts as the real date when the sheet is started.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CURRENT_DATE WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- V3__person.sql
-- The people on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    CHAR(1)      NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- V4__person_name_unique.sql
-- A person's name is unique on the sheet, compared without case and ignoring surrounding spaces.
-- Names are stored trimmed; name_key is the trimmed, lower-cased name the uniqueness is kept on.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200);
UPDATE person SET name_key = LOWER(name);
ALTER TABLE person ALTER COLUMN name_key SET NOT NULL;
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- V5__claim.sql
-- A person's claims: an amount (0.00 or more, two decimals), a date and a note (may be empty).
-- Listed newest first (by id).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(500)   NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- V6__rate.sql
-- The sheet's rate for each grade: a percent with two decimals (0.00 or more). A grade with no row
-- has no rate, and its claims' due is n/a.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    CHAR(1)      NOT NULL,
    pct      DECIMAL(7, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- V7__claim_status.sql
-- A claim's status: DRAFT when added, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID.
-- Only OPEN and SETTLED claims count toward what is claimed and due.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
-- V8__claim_number.sql
-- A claim's number: given when the claim is opened, the next on its sheet (1, 2, ...), never
-- reused. A DRAFT claim has none; voiding a claim clears it. The sheet keeps the last number given.
ALTER TABLE sheet ADD COLUMN last_claim_number BIGINT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number BIGINT;
CREATE UNIQUE INDEX claim_sheet_number ON claim (sheet_id, claim_number);
-- V9__claim_settled_due.sql
-- A claim's due, fixed when it is settled: its amount times its person's grade rate at that moment.
-- Empty while the claim is not settled, or when it was settled with no rate for the grade (its due
-- then stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);
-- V10__rate_from.sql
-- A rate may carry a from-date: a grade may have several rates, and a claim takes the one whose
-- from-date is the latest on or before its date. A rate with no from-date applies from the
-- beginning of time. One rate per grade and from-date (the service keeps the no-from-date one
-- unique, since NULLs are distinct in a unique index).
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_date);
-- V11__claim_opened_by.sql
-- Who opened a claim: the signed-in user's name, given when it is opened. Empty while DRAFT.
-- That user cannot settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(100);
-- V12__person_version.sql
-- The version of a person, moved on by each save. An edit names the version it was made from and
-- is refused when someone else has saved the person since.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
-- V13__statement.sql
-- A claim's figure bound by its person's last statement: stated is set on each claim that counted
-- when the statement was taken, with the due it had then (empty when it had none). The claim then
-- shows and totals that figure until the person's next statement rebinds or clears it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);

-- Each statement taken for a person: their due-total at that moment (empty when it was n/a) and the
-- sheet's today when it was taken.
CREATE TABLE statement (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id      BIGINT       NOT NULL REFERENCES person (id),
    due_total      DECIMAL(14, 2),
    statement_date DATE         NOT NULL,
    taken_by       VARCHAR(100) NOT NULL
);
CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
-- V14__period.sql
-- The sheet's periods: a name unique on the sheet and a from and to date, both inclusive. No two
-- periods on a sheet overlap (the service checks this under the sheet's lock). A claim belongs to
-- the period whose dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(100) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name);
-- V15__period_closed.sql
-- A period can be closed. Closing fixes its due-total at that moment: the dues of the claims that
-- count whose date falls in it. No claim dated inside a closed period can then be added, edited,
-- opened, settled or voided. The fixed due-total is empty while the period is open.
ALTER TABLE period ADD COLUMN closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE period ADD COLUMN closed_due_total DECIMAL(14, 2);
-- V16__person_retired.sql
-- A person can be retired from a date; set, they count as retired at once whatever the date. No
-- claim of theirs dated after it can be added or edited to such a date. Empty while not retired.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- V17__person_held.sql
-- A person can be put on hold and taken off it again. While held, their OPEN claims count in no
-- live total; their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
-- V18__roles_clerk_limit.sql
-- The sheet's clerk limit: a clerk can settle a claim only when its due is at or below it. NULL
-- means no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(14, 2);
-- The role a user name has on a sheet; a name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL
);
CREATE UNIQUE INDEX sheet_role_user ON sheet_role (sheet_id, user_name);
-- V19__sheet_floor.sql
-- The sheet's floor: a claim's live due is at least it. Every sheet starts at 1.00.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(14, 2) DEFAULT 1.00 NOT NULL;
-- V20__sheet_terms.sql
-- The sheet's terms in days: a claim's due-by is its date plus them. Every sheet starts at 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL;
-- V21__sheet_late_pct.sql
-- The sheet's late percent: an overdue claim's due gains it of its figure for every full 30 days
-- it is overdue. Every sheet starts at 0.00.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(7, 2) DEFAULT 0.00 NOT NULL;
-- V22__person_patron.sql
-- A person's patrons: other people on the same sheet they have named, each at most once.
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CONSTRAINT person_patron_not_self CHECK (person_id <> patron_id)
);
CREATE UNIQUE INDEX person_patron_unique ON person_patron (person_id, patron_id);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, person_id);
-- V23__person_grade.sql
-- A person's grade is dated: person.grade is the first grade they were given, in force from the
-- beginning of time; each later grade recorded is a row here, in force from its from-date until the
-- next one. One grade per person and from-date.
CREATE TABLE person_grade (
    person_id BIGINT  NOT NULL REFERENCES person (id),
    from_date DATE    NOT NULL,
    grade     CHAR(1) NOT NULL,
    PRIMARY KEY (person_id, from_date)
);
-- V25__claim_corrects.sql
-- A correction (a claim with a negative amount) names, by number, the SETTLED claim of the same
-- person that it corrects. Empty for any other claim.
ALTER TABLE claim ADD COLUMN corrects BIGINT;
-- V26__sheet_policy_date.sql
-- The sheet's policy date: a claim dated before it rounds half up, one on or after it half to even.
-- Empty: the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
-- V27__period_numbering.sql
-- The sheet's period numbering from: while set and the sheet's today is on or after it, a claim
-- opened is numbered within its period (<period name>-<n>), or X-<n> when in no period. Empty: off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim's number is now text: the sheet-wide number (1, 2, ...) or a number within a period.
-- A correction names the number of the claim it corrects in the same form.
DROP INDEX claim_sheet_number;
ALTER TABLE claim ALTER COLUMN claim_number VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects VARCHAR(220);
-- A claim numbered within a period: the period's name (empty: in no period) and its place in it.
ALTER TABLE claim ADD COLUMN number_period VARCHAR(200);
ALTER TABLE claim ADD COLUMN number_seq INT;
-- V30__grade_terms_claim_due_by.sql
-- Terms can be set per grade: a grade with a row here uses its terms, any other the sheet's terms.
CREATE TABLE sheet_grade_terms (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    CHAR(1)      NOT NULL,
    terms    INT          NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);

-- A claim's due-by is fixed when it is added. Existing claims keep the due-by they show: their
-- date plus their sheet's terms.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = claim.sheet_id), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- V31__claim_log.sql
-- Each claim's status log, oldest first: one line per status it has had (DRAFT when added), who
-- gave it, the sheet's today then and the claim's due as it was computed at that moment (empty
-- when it had none). Claims added before the log was kept start with no lines.
CREATE TABLE claim_log (
    claim_id  BIGINT       NOT NULL REFERENCES claim (id),
    seq       INT          NOT NULL,
    status    VARCHAR(20)  NOT NULL,
    by_user   VARCHAR(100) NOT NULL,
    log_date  DATE         NOT NULL,
    due       DECIMAL(14, 2),
    PRIMARY KEY (claim_id, seq)
);
-- V32__person_hold.sql
-- A person may have several holds over time, each from a from-date to an optional to-date (null:
-- open-ended). Only their open claims dated within a hold, and not bound by a statement, are left
-- out of the live totals. A person held before holds had dates is held from the beginning of time
-- (a null from-date).
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, NULL, NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- V33__rate_to.sql
-- A rate may carry a to-date: it applies through that date. A claim dated after the to-date of the
-- rate that would apply to it (the latest from-date on or before its date) has no rate, and its
-- due is n/a. Null applies with no end.
ALTER TABLE rate ADD COLUMN to_date DATE;
-- V34__sheet_cap.sql
-- The sheet's cap: a person's due-total is at most it, the rest shown as their excess. Null means
-- none.
ALTER TABLE sheet ADD COLUMN due_cap DECIMAL(14, 2);
-- V35__period_person_due.sql
-- Closing a period also fixes each person's due-total for it at that moment, for every person on
-- the sheet: the dues of their claims that count whose date falls in it. A person added later has
-- no line and shows 0.00. Reopening the period removes its lines: the figures are live again.
CREATE TABLE period_person_due (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    due_total DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- V36__sheet_setting_dated.sql
-- Settings that carry a figure are dated: each value is recorded from a from-date, and the value in
-- force on a date is the one with the latest from-date on or before it. Before every from-date the
-- floor is 1.00, the late percent 0.00 and the terms 14; a grade's terms are the sheet's, and the
-- clerk limit and the cap are none. A null value is none (a cleared clerk limit or cap).
CREATE TABLE sheet_setting (
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(40)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(40),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);

-- Existing sheets keep the values they show: each set value is recorded from the earliest date.
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'floor', DATE '0001-01-01', CAST(due_floor AS VARCHAR) FROM sheet WHERE due_floor <> 1.00;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'late-pct', DATE '0001-01-01', CAST(late_pct AS VARCHAR) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'terms', DATE '0001-01-01', CAST(terms AS VARCHAR) FROM sheet WHERE terms <> 14;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'clerk-limit', DATE '0001-01-01', CAST(clerk_limit AS VARCHAR) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'cap', DATE '0001-01-01', CAST(due_cap AS VARCHAR) FROM sheet WHERE due_cap IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, 'terms-' || grade, DATE '0001-01-01', CAST(terms AS VARCHAR) FROM sheet_grade_terms;

DROP TABLE sheet_grade_terms;
ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN late_pct;
ALTER TABLE sheet DROP COLUMN terms;
ALTER TABLE sheet DROP COLUMN clerk_limit;
ALTER TABLE sheet DROP COLUMN due_cap;
-- V37__claim_deferred_until.sql
-- An OPEN claim can be deferred to a date after the sheet's today: until the sheet's today reaches
-- it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
-- statement. Null: never deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
-- V38__claim_proofs.sql
-- A claim's proofs count, raised one at a time. A claim whose due is above the sheet's proof threshold
-- in force on its date cannot be settled or approved while it has none. Existing claims have none.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
-- V39__sheet_permission.sql
-- The sheet's permission matrix: for an action (open, settle, void, reassign, close, reopen), the roles
-- that may take it, comma separated. An action with no row keeps the standing rule: open, settle, void
-- and close by clerk and steward; reassign and reopen by steward.
CREATE TABLE sheet_permission (
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    perm_action  VARCHAR(20)  NOT NULL,
    perm_roles   VARCHAR(100) NOT NULL,
    PRIMARY KEY (sheet_id, perm_action)
);
-- V40__sheet_grace_days.sql
-- The sheet's grace days (not dated): when its today is changed, every open period whose to-date plus
-- them is before the new today is closed. Null means off.
ALTER TABLE sheet ADD COLUMN grace_days INTEGER;
-- V41__claim_split_from.sql
-- A claim split off an OPEN claim names, by number, the claim it was split from. Empty for any other claim.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(220);
-- V42__person_watch.sql
-- The users watching a person on a sheet, each at most once; the id orders them by when they started.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX person_watch_unique ON person_watch (person_id, user_name);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
-- V43__delegation.sql
-- A steward's role delegated to a user name on a sheet for a from-date and a to-date, inclusive; the id
-- orders them by when they were made.
CREATE TABLE delegation (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name  VARCHAR(100) NOT NULL,
    delegator  VARCHAR(100) NOT NULL,
    from_date  DATE         NOT NULL,
    to_date    DATE         NOT NULL
);
CREATE INDEX delegation_sheet_user ON delegation (sheet_id, user_name);
-- V44__sheet_archived.sql
-- Whether a steward has archived the sheet: an archived sheet stays visible and refuses every change.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
-- V45__person_terms.sql
-- A person may have their own terms in days, used for their claims' due-by ahead of their grade's
-- and the sheet's; null: none.
ALTER TABLE person ADD COLUMN terms INT;
-- V46__claim_number_retired.sql
-- A place in a period's numbering given up by a claim re-dated into another period: never given again.
CREATE TABLE claim_number_retired (
    sheet_id VARCHAR(100) NOT NULL,
    number_period VARCHAR(200) NOT NULL,
    number_seq INT NOT NULL,
    PRIMARY KEY (sheet_id, number_period, number_seq)
);
-- V47__claim_locked_by.sql
-- The user whose open editor locks the claim for everyone else; none while no editor holds it.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(100);
-- V48__period_soft_closed.sql
-- A period can be soft-closed: its due-total and each person's due-total for it are fixed at that
-- moment, as for a close, but claims dated inside it can still be added, edited, opened, settled
-- and voided. A soft-closed period is not closed; it can be closed (fixing the figures afresh) or
-- reopened.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN NOT NULL DEFAULT FALSE;
-- A claim added while the period its date falls in was soft-closed is a late entry.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN NOT NULL DEFAULT FALSE;
-- V49__statement_as_of.sql
-- A statement can be taken as of a date on or before the sheet's today: it binds the person's claims
-- that counted at the end of that date to their figures as they stood then, counting every change
-- made while the sheet's today was on or before it and no later one. So each change a figure hangs on
-- records the sheet's today it was made on (empty: made before this was kept, which always counts).

-- The sheet's today when the statement was taken; statement_date is the date it is as of (the same
-- for a statement taken now).
ALTER TABLE statement ADD COLUMN taken_on DATE;
UPDATE statement SET taken_on = statement_date;

-- The sheet's today when the person was added; no statement is taken as of a date before it.
ALTER TABLE person ADD COLUMN added_on DATE;

-- The sheet's today when their retirement date was last set.
ALTER TABLE person ADD COLUMN retired_on DATE;

-- The sheet's today when each hold was put on.
ALTER TABLE person_hold ADD COLUMN set_on DATE;

-- Each grade recorded for a person after the first, oldest first, with the sheet's today it was
-- recorded on; a later line for the same from-date replaces an earlier one from when it was recorded.
CREATE TABLE person_grade_log (
    person_id BIGINT  NOT NULL REFERENCES person (id),
    seq       INT     NOT NULL,
    from_date DATE    NOT NULL,
    grade     CHAR(1) NOT NULL,
    set_on    DATE,
    PRIMARY KEY (person_id, seq)
);
INSERT INTO person_grade_log (person_id, seq, from_date, grade, set_on)
    SELECT person_id, ROW_NUMBER() OVER (PARTITION BY person_id ORDER BY from_date) - 1, from_date, grade, NULL
    FROM person_grade;

-- Each rate set, oldest first, with the sheet's today it was set on; a later line for the same grade
-- and from-date replaces an earlier one from when it was set.
CREATE TABLE rate_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade     CHAR(1)       NOT NULL,
    from_date DATE,
    to_date   DATE,
    pct       DECIMAL(7, 2) NOT NULL,
    set_on    DATE
);
CREATE INDEX rate_log_sheet ON rate_log (sheet_id, id);
INSERT INTO rate_log (sheet_id, grade, from_date, to_date, pct, set_on)
    SELECT sheet_id, grade, from_date, to_date, pct, NULL FROM rate ORDER BY id;

-- Each dated setting value recorded, oldest first, with the sheet's today it was recorded on; a later
-- line for the same key and from-date replaces an earlier one from when it was recorded.
CREATE TABLE sheet_setting_log (
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    seq           INT          NOT NULL,
    setting_key   VARCHAR(40)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(40),
    set_on        DATE,
    PRIMARY KEY (sheet_id, seq)
);
INSERT INTO sheet_setting_log (sheet_id, seq, setting_key, from_date, setting_value, set_on)
    SELECT sheet_id, ROW_NUMBER() OVER (PARTITION BY sheet_id ORDER BY setting_key, from_date) - 1,
           setting_key, from_date, setting_value, NULL
    FROM sheet_setting;

-- The sheet's today when the claim was deferred.
ALTER TABLE claim ADD COLUMN deferred_on DATE;

-- Each binding of a claim by a statement and each release of it, oldest first, with the sheet's today
-- then: stated, with the figure bound (empty when none), or not. A claim with no lines is bound as
-- its stated column says.
CREATE TABLE claim_binding (
    claim_id BIGINT  NOT NULL REFERENCES claim (id),
    seq      INT     NOT NULL,
    on_date  DATE    NOT NULL,
    stated   BOOLEAN NOT NULL,
    due      DECIMAL(14, 2),
    PRIMARY KEY (claim_id, seq)
);
-- V50__sheet_snapshot.sql
-- What a sheet held after each change to it, oldest first, so it can be shown as of a date: every
-- row the sheet owns, in every table, with the sheet's today once the change was made (empty: the
-- sheet as it was started, which stands for any date before its first change). A change that left
-- the sheet as it was records nothing.
CREATE TABLE sheet_snapshot (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL,
    taken_on DATE,
    data     VARBINARY NOT NULL
);
CREATE INDEX sheet_snapshot_sheet ON sheet_snapshot (sheet_id, id);
-- V51__sheet_entry_date.sql
-- The sheet's entry date (not dated): while set, a new claim given no date takes it rather than the
-- sheet's today. Null means off.
ALTER TABLE sheet ADD COLUMN entry_date DATE;
-- V52__claim_reminded.sql
-- The last sheet-today a reminder was written for the claim; none until reminded.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
-- V53__holiday.sql
-- The sheet's holidays, each date at most once; a claim's due-by is moved past them when it is added.
CREATE TABLE holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE         NOT NULL
);
CREATE UNIQUE INDEX holiday_unique ON holiday (sheet_id, holiday_date);
-- V55__claim_ref.sql
-- A claim may carry an external reference, stored trimmed; none for a claim without one. It is unique on
-- the sheet without regard to case: ref_key is the lower-cased reference the uniqueness is kept on.
ALTER TABLE claim ADD COLUMN ref VARCHAR(200);
ALTER TABLE claim ADD COLUMN ref_key VARCHAR(200);
CREATE UNIQUE INDEX claim_sheet_ref ON claim (sheet_id, ref_key);
-- V56__claim_tags.sql
-- A claim may carry tags: trimmed, lower-cased, each once, kept sorted and comma separated; empty for none.
ALTER TABLE claim ADD COLUMN tags VARCHAR(2000) NOT NULL DEFAULT '';
-- Every tag ever used on a claim of the sheet, each once; the sheet shows a due-total for each.
CREATE TABLE claim_tag (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    tag      VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX claim_tag_unique ON claim_tag (sheet_id, tag);
-- V57__void_reason.sql
-- The sheet's void reasons, each once; while any are on the list, a claim is voided with one of them.
CREATE TABLE void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX void_reason_unique ON void_reason (sheet_id, reason);
-- The reason a VOID claim was voided with; none when voided without one.
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
-- V58__claim_comment.sql
-- Each claim's comments, oldest first: the text, who wrote it and the sheet's today when it was written.
CREATE TABLE claim_comment (
    claim_id     BIGINT        NOT NULL REFERENCES claim (id),
    seq          INT           NOT NULL,
    by_user      VARCHAR(100)  NOT NULL,
    comment_date DATE          NOT NULL,
    comment_text VARCHAR(500)  NOT NULL,
    PRIMARY KEY (claim_id, seq)
);
-- V59__claim_edited_by.sql
-- Who last edited a claim (its form or its row's amount entry); none while never edited.
-- That user cannot settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(100);
-- V61__settle_batch.sql
-- A bulk settle that settles at least one claim (to SETTLED or PENDING) is a batch, numbered 1, 2, ...
-- on the sheet; each claim it settled keeps its batch number (none when settled one at a time).
ALTER TABLE sheet ADD COLUMN last_settle_batch INT NOT NULL DEFAULT 0;
ALTER TABLE claim ADD COLUMN settle_batch INT;
-- V62__person_contact.sql
-- A person may have a contact, stored without surrounding spaces and lower-cased; null: none. A
-- contact is unique on the sheet.
ALTER TABLE person ADD COLUMN contact VARCHAR(200);
CREATE UNIQUE INDEX person_sheet_contact ON person (sheet_id, contact);
-- V63__person_alias.sql
-- A person's aliases, each stored without surrounding spaces; alias_key is the trimmed, lower-cased
-- alias. An alias is unique on the sheet among aliases (here) and names (kept by the service).
CREATE TABLE person_alias (
    person_id BIGINT       NOT NULL REFERENCES person (id),
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) NOT NULL
);
CREATE INDEX person_alias_person ON person_alias (person_id);
CREATE UNIQUE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);
-- V64__claim_template.sql
-- The sheet's claim templates, each name once: a DRAFT claim made from one takes its amount and note then.
CREATE TABLE claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200)   NOT NULL,
    amount   DECIMAL(14, 2) NOT NULL,
    note     VARCHAR(500)   NOT NULL
);
CREATE UNIQUE INDEX claim_template_unique ON claim_template (sheet_id, name);
-- V65__pool.sql
-- The sheet's pools, each name once, stored without surrounding spaces.
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX pool_unique ON pool (sheet_id, name);
-- A pool's members, each person at most once in a pool, with their share percent (two decimals).
CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id   BIGINT        NOT NULL REFERENCES pool (id),
    sheet_id  VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    person_id BIGINT        NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL
);
CREATE UNIQUE INDEX pool_member_unique ON pool_member (pool_id, person_id);
-- V66__sheet_pot.sql
-- The sheet's pot (not dated): split across each balanced pool's members as their cuts. Null means
-- none.
ALTER TABLE sheet ADD COLUMN pot DECIMAL(14, 2);
-- V67__person_merged_into.sql
-- A person merged into another is kept, naming the person they were merged into, and leaves the
-- sheet: no list, figure or lookup includes them. Not a reference, so the sheet's history can put
-- its people back in any order.
ALTER TABLE person ADD COLUMN merged_into BIGINT;
-- V68__sheet_parent.sql
-- The sheet a sheet names as its parent (not dated): a grade with no rate in force on a date on the
-- sheet takes its parent's, then its parent's parent's, up to three levels up. Kept apart from the
-- sheet's own rows (no sheet_id column, no reference) so its history leaves it as it is now: the
-- link between sheets is not part of what either sheet held on a date.
CREATE TABLE sheet_parent (
    child_sheet  VARCHAR(100) PRIMARY KEY,
    parent_sheet VARCHAR(100) NOT NULL
);
-- V69__claim_deleted.sql
-- A DRAFT claim may be DELETED: it counts nowhere and cannot change, unless restored to DRAFT on the
-- same sheet's today it was deleted.
ALTER TABLE claim DROP CONSTRAINT claim_status_check;
ALTER TABLE claim ADD CONSTRAINT claim_status_check
    CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'DELETED'));
-- V70__pool_member_pool.sql
-- A pool's member is a person or another pool (member_pool_id, the person then null). A pool is a
-- member of at most one pool.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool (id);
CREATE UNIQUE INDEX pool_member_pool_unique ON pool_member (member_pool_id);
ALTER TABLE pool_member ADD CONSTRAINT pool_member_one_check
    CHECK ((person_id IS NULL) <> (member_pool_id IS NULL));
-- V71__person_position.sql
-- People have a position in the sheet's list, smallest first; existing people keep the order they were
-- added in (by id). New people go to the end.
ALTER TABLE person ADD COLUMN list_position BIGINT;
UPDATE person SET list_position = id;
ALTER TABLE person ALTER COLUMN list_position SET NOT NULL;
CREATE INDEX person_sheet_position ON person (sheet_id, list_position);
-- V72__person_transferred_from.sql
-- A transferred person keeps the id of the sheet they came from; null for anyone else.
ALTER TABLE person ADD COLUMN transferred_from VARCHAR(100);
-- V73__pool_member_dates.sql
-- A pool membership may carry a from-date and a to-date, both included (null: no bound). A member whose
-- dates do not include the sheet's today is left out of its pool: no share in the total, no cut.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
-- V74__person_retirement.sql
-- A retired person can be unretired. Each past retirement is kept, from its from-date to the sheet's
-- today it was ended on, with the sheet's today it was set on (null: set before this was kept). No
-- claim of theirs may be dated after the from-date and before the to-date of one.
CREATE TABLE person_retirement (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE NOT NULL,
    to_date   DATE NOT NULL,
    set_on    DATE
);
CREATE INDEX person_retirement_person ON person_retirement (person_id);
