            }
        }
        try (Statement query = connection.createStatement();
                ResultSet rows = query.executeQuery("SELECT person_id, from_date, grade FROM person_grade")) {
            while (rows.next()) {
                PersonRow person = people.get(rows.getLong(1));
                if (person != null) person.datedGrades().put(rows.getDate(2).toLocalDate(), rows.getString(3));
            }
        }

        List<ClaimRow> claims = new ArrayList<>();
        try (Statement query = connection.createStatement();
                ResultSet rows = query.executeQuery("SELECT id, sheet_id, person_id, claim_date, due_by FROM claim")) {
            while (rows.next()) {
                claims.add(new ClaimRow(rows.getLong(1), rows.getString(2), rows.getLong(3),
                        rows.getDate(4).toLocalDate(), rows.getDate(5).toLocalDate()));
            }
        }

        try (PreparedStatement update = connection.prepareStatement("UPDATE claim SET due_by = ? WHERE id = ?")) {
            for (ClaimRow claim : claims) {
                Set<LocalDate> sheetHolidays = holidays.getOrDefault(claim.sheetId(), Set.of());
                int terms = termsFixed(claim, people.get(claim.personId()),
                        settings.getOrDefault(claim.sheetId(), Map.of()), sheetHolidays);
                LocalDate dueBy = businessDaysAfter(claim.date(), terms, sheetHolidays);
                if (dueBy.equals(claim.dueBy())) continue;
                update.setDate(1, Date.valueOf(dueBy));
                update.setLong(2, claim.id());
                update.addBatch();
            }
            update.executeBatch();
        }
    }

    /** The terms the claim was fixed with, in days. */
    private static int termsFixed(ClaimRow claim, PersonRow person, Map<String, TreeMap<LocalDate, Integer>> settings,
            Set<LocalDate> holidays) {
        Integer terms = person == null ? null : person.terms();
        if (terms == null && person != null) {
            Map.Entry<LocalDate, String> dated = person.datedGrades().floorEntry(claim.date());
            String grade = dated == null ? person.grade() : dated.getValue();
            terms = valueOn(settings.get("terms-" + grade), claim.date());
        }
        if (terms == null) terms = valueOn(settings.get("terms"), claim.date());
        if (terms == null) terms = START_TERMS;
        LocalDate plain = claim.date().plusDays(terms);
        if (!plain.isAfter(claim.dueBy())) {
            LocalDate d = plain;
            while (d.isBefore(claim.dueBy()) && holidays.contains(d)) d = d.plusDays(1);
            if (d.equals(claim.dueBy())) return terms;
        }
        return (int) Math.max(0, ChronoUnit.DAYS.between(claim.date(), claim.dueBy()));
    }

    private static Integer valueOn(TreeMap<LocalDate, Integer> values, LocalDate date) {
        if (values == null) return null;
        Map.Entry<LocalDate, Integer> on = values.floorEntry(date);
        return on == null ? null : on.getValue();
    }

    private static LocalDate businessDaysAfter(LocalDate date, int terms, Set<LocalDate> holidays) {
        LocalDate d = date;
        for (int left = terms; left > 0; ) {
            d = d.plusDays(1);
            DayOfWeek day = d.getDayOfWeek();
            if (day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !holidays.contains(d)) left--;
        }
        return d;
    }
}
package db.migration;


/**
 * A claim keeps the terms its due-by was fixed with, so a holiday added later can fix it again. For an
 * existing claim they are the business days from its date to its due-by, over the sheet's holidays now
 * (none for a due-by on or before its date).
 */
public class V60__claim_terms extends BaseJavaMigration {

    @Override
    public void migrate(Context context) throws Exception {
        Connection connection = context.getConnection();
        try (Statement ddl = connection.createStatement()) {
            ddl.execute("ALTER TABLE claim ADD COLUMN terms INT NOT NULL DEFAULT 0");
        }

        Map<String, Set<LocalDate>> holidays = new HashMap<>();
        try (Statement query = connection.createStatement();
                ResultSet rows = query.executeQuery("SELECT sheet_id, holiday_date FROM holiday")) {
            while (rows.next()) {
                holidays.computeIfAbsent(rows.getString(1), k -> new HashSet<>()).add(rows.getDate(2).toLocalDate());
            }
        }

        try (Statement query = connection.createStatement();
                ResultSet rows = query.executeQuery("SELECT id, sheet_id, claim_date, due_by FROM claim");
                PreparedStatement update = connection.prepareStatement("UPDATE claim SET terms = ? WHERE id = ?")) {
            while (rows.next()) {
                Set<LocalDate> sheetHolidays = holidays.getOrDefault(rows.getString(2), Set.of());
                LocalDate date = rows.getDate(3).toLocalDate();
                LocalDate dueBy = rows.getDate(4).toLocalDate();
                int terms = 0;
                for (LocalDate d = date.plusDays(1); !d.isAfter(dueBy); d = d.plusDays(1)) {
                    DayOfWeek day = d.getDayOfWeek();
                    if (day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !sheetHolidays.contains(d)) terms++;
                }
                if (terms == 0) continue;
                update.setInt(1, terms);
                update.setLong(2, rows.getLong(1));
                update.addBatch();
            }
            update.executeBatch();
        }
    }
}
package net.officefloor.hq.app.sheet;

import java.time.Instant;
import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Loads a sheet by id; an id never used before starts a new, empty sheet whose today is the real
 * date. After that the sheet's today is the only date the app uses for it ({@link #today}).
 */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollup;
    // looked up when used: the periods depend on the claims, which depend on the sheet
    private final ObjectProvider<PeriodService> periods;
    private final ObjectProvider<SettingService> settings;
    private final ObjectProvider<ClaimRepository> claims;
    private final Audit audit;

    public SheetService(SheetRepository sheets, RollupService rollup, ObjectProvider<PeriodService> periods,
            ObjectProvider<SettingService> settings, ObjectProvider<ClaimRepository> claims, Audit audit) {
        this.claims = claims;
        this.sheets = sheets;
        this.rollup = rollup;
        this.periods = periods;
        this.settings = settings;
        this.audit = audit;
    }

    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
            } catch (DataIntegrityViolationException raced) {
                // another user started the same sheet at the same moment
                return sheets.findById(id).orElseThrow(() -> raced);
            }
        });
    }

    /** The sheet's today: use this, never the real clock, for any date decision or default date. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseThrow(SheetNotFoundException::new);
    }

    /**
     * Lock the sheet for numbering a claim: its sheet-wide numbers are 1, 2, ... with no gaps and never
     * reused, and so are its numbers within each period. The sheet stays locked until the caller's
     * transaction ends, so two users opening claims at once get different numbers.
     */
    @Transactional
    public Sheet lockForNumbering(String id) {
        return sheets.findForUpdate(id).orElseThrow(SheetNotFoundException::new);
    }

    /**
     * Change the sheet's today; it has no audit line of its own, but a new today first audits a SNAPSHOT
     * line per person, in list order, with their due-total on the day being left. With grace days set, the open periods
     * past them are closed first, then the figures it moves are audited. A new today releases every
     * claim editor's lock on the sheet.
     */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = sheets.findForUpdate(id).orElseThrow(SheetNotFoundException::new);
        boolean changed = !today.equals(sheet.getToday());
        if (changed) {
            claims.getObject().unlockAll(id);
            sheet = sheets.findForUpdate(id).orElseThrow(SheetNotFoundException::new);
        }
        RollupService.Snapshot before = rollup.snapshot(id);
        if (changed) rollup.recordSnapshot(id, user, before);
        sheet.setToday(today);
        sheets.flush();
        if (sheet.getGraceDays() != null) periods.getObject().autoClose(id, user, today, sheet.getGraceDays());
        rollup.recordChanges(id, user, before);
        return sheet;
    }

    /** Archive the sheet, as a steward (or one acting for a steward); anyone else is refused. */
    @Transactional
    public Sheet archive(String id, String user) {
        Sheet sheet = sheets.findForUpdate(id).orElseThrow(SheetNotFoundException::new);
        if (sheet.isArchived()) throw new SheetArchivedException();
        if (settings.getObject().roleOf(id, user) != Role.STEWARD) throw new SheetArchiveRefusedException();
        sheet.archive();
        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + user);
        return sheet;
    }

    /** The number of the sheet's last settle batch; 0 while there has been none. */
    @Transactional(readOnly = true)
    public int lastSettleBatch(String id) {
        return sheets.findById(id).map(Sheet::getLastSettleBatch).orElse(0);
    }

    /** Whether the sheet has been archived: every change to it is refused. */
    @Transactional(readOnly = true)
    public boolean isArchived(String id) {
        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.asof.AsOfRead;
import net.officefloor.hq.app.setting.OpenToViewer;
import net.officefloor.hq.app.setting.SettingController;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets")
public class SheetController {

    /**
     * A sheet as the screen shows it; the floor, the terms, the late percent and the cap are those in
     * force on its today: the floor has two decimals, the terms are in days, the late percent has two
     * decimals; the policy date is null when blank (the sheet's today); the cap has two decimals, null
     * when none; dated has every value recorded for its dated settings, by key; archived is whether a
     * steward has archived it; last batch is the number of its last bulk settle batch, null when none.
     */
    public record SheetView(String id, LocalDate today, String floor, int terms, String latePct,
            LocalDate policyDate, String cap, Map<String, List<SettingController.DatedView>> dated,
            boolean archived, Integer lastBatch) {
        static SheetView of(Sheet sheet) {
            LocalDate today = sheet.getToday();
            return new SheetView(sheet.getId(), today, sheet.floorOn(today).toPlainString(),
                    sheet.termsOn(today), sheet.latePctOn(today).toPlainString(), sheet.getPolicyDate(),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    SettingController.datedViews(sheet.getDated()), sheet.isArchived(),
                    sheet.getLastSettleBatch() == 0 ? null : sheet.getLastSettleBatch());
        }
    }

    public record TodayRequest(@NotNull LocalDate today) {}

    private final SheetService service;

    public SheetController(SheetService service) {
        this.service = service;
    }

    /** Load (or start) a sheet by id for the signed-in user. */
    @OpenToViewer
    @AsOfRead
    @PostMapping("/{id}/load")
    public SheetView load(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return SheetView.of(service.load(id, user.trim()));
    }

    /** Change the sheet's today. */
    @PutMapping("/{id}/today")
    public SheetView setToday(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid TodayRequest request) {
        return SheetView.of(service.setToday(id, user, request.today()));
    }

    /** Archive the sheet: a steward only; an archived sheet refuses it as it does every change. */
    @PostMapping("/{id}/archive")
    public SheetView archive(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return SheetView.of(service.archive(id, user.trim()));
    }
}

